            return [replace_emails(item) for item in obj]
        elif isinstance(obj, str) and re.match(email_pattern, obj):
            return REPLACE_NONE
        else:
            return obj
    final_data = replace_emails(processed_data)
    return {"data": final_data, "value_counts": value_counts}
